import{createUpperWater}from'./upper-water.mjs';
const moduleURL=import.meta.url,pins={"open_upper_source.bin":{"sha256":"e1728d0a526578f73b68c7a9d959afac8976c84f4abbc3512a593566378dcfba","bytes":2082240},"open_upper_gain.bin":{"sha256":"eb655907df25fe135a5e09e107640b02b0db26086564fe6ef7eb69d2a4efa319","bytes":4164480},"open_upper_allowed.bin":{"sha256":"7dad2364f42cbea0b710e34e1d93e9ece5846b586bbb28a2bb23c631825d2d57","bytes":520560}};
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
export async function loadUpperWater({fetcher=fetch,signal}={}){const check=()=>{if(signal?.aborted)throw Error('UPPER_CANCELLED')};check();const read=async name=>{check();const r=await fetcher(new URL('assets/'+name,moduleURL),{signal});if(!r.ok)throw Error('UPPER_HTTP');const raw=await r.arrayBuffer(),b=raw instanceof ArrayBuffer?new Uint8Array(raw.slice(0)):new Uint8Array(raw);check();if(b.length!==pins[name].bytes||await sha(b)!==pins[name].sha256)throw Error('UPPER_INPUT_PIN');return b};const[source,gb,allowed]=await Promise.all(['open_upper_source.bin','open_upper_gain.bin','open_upper_allowed.bin'].map(read));check();const gain=new Float64Array(gb.length/8),view=new DataView(gb.buffer);for(let i=0;i<gain.length;i++)gain[i]=view.getFloat64(i*8,true);const layer=createUpperWater({source,gain,allowed});try{check();return layer}catch(e){layer.dispose();throw e}}
